//! `TLAplusParserTokenManager` + `SimpleCharStream`, mirrored. The DFA/NFA tables and
//! literal images are generated by `xtask jj2rs` from the pinned TokenManager (5,334 lines);
//! only `SimpleCharStream` and the token-manager driver loop are hand-ported.
//!
//! Columns count Java `char`s (UTF-16 units) with tabs advancing to the next multiple of 8
//! (`SimpleCharStream.java:168-170`), because junction-list alignment compares them.
//! Lexing does *not* intern; TLC interns token images when a `SyntaxTreeNode` is built.

/// JavaCC lexical states used by TLC. `Cfg` is state 2, reused by `ModelConfig`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum LexState {
    Default = 0,
    Pragma = 1,
    Cfg = 2,
    // comment / proof-step states ...
}

/// Token kind numbers are the generated `TLAplusParserConstants` values, because the
/// parser's `jj_la1` expected-token bitsets index by them.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct TokenKind(pub(crate) u16);

#[derive(Clone, Debug)]
pub(crate) struct Token {
    pub(crate) kind: TokenKind,
    pub(crate) image: Box<str>,
    pub(crate) begin_line: u32,
    pub(crate) begin_column: u32,
    pub(crate) end_line: u32,
    pub(crate) end_column: u32,
}

pub(crate) struct SimpleCharStream<'s> {
    text: &'s str,
    pos: usize,
    line: u32,
    column: u32,
}

pub(crate) struct TokenManager<'s> {
    stream: SimpleCharStream<'s>,
    state: LexState,
    /// `(* *)` nesting depth.
    bracket_count: u32,
}

/// `Lexical {error: EOF reached, possibly open comment starting around line N` etc.
#[derive(Debug)]
pub(crate) struct LexicalError {
    pub(crate) text: String,
}

impl<'s> TokenManager<'s> {
    pub(crate) fn new(text: &'s str, state: LexState) -> Self {
        todo!()
    }
    /// `getNextToken`. Text outside `----+ MODULE` is skipped; `BAND`/`BOR` odd tokens,
    /// `WF_`/`SF_` exclusions, proof-step tokens and keyword-as-field-name follow the grammar.
    pub(crate) fn next_token(&mut self) -> Result<Token, LexicalError> {
        todo!()
    }
}
